using System;using System.IO;using System.Collections.Generic;using System.Globalization;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
// 隔離プレビュー専用。ゲームのシーン・資産・水には触れない。
public static class CaveKitChecks {
 [Serializable]class Report{public string status,error;public int checks,placed;public float maxRootError;}
 static int count;static void Check(bool v,string why){count++;if(!v)throw new Exception(why);}static string Arg(string s){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,s)+1];}
 public static void Run(){var output=Arg("-cave-output");var report=new Report();int code=0;try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var export=Path.Combine(output,"export");var lib=MapSharedPropsBuilder.ReadLibrary(Path.Combine(export,"shared_props.json"));var built=MapSharedPropsBuilder.Build(export);Check(built.placed==3&&built.skipped==0,"3 shared placements");report.placed=built.placed;
 foreach(var id in new[]{"stalagmite","flowstone","cavebreakdown"}){var a=Array.Find(lib.assets,x=>x.id==id);var prefab=built.prefabs[id];var mesh=prefab.GetComponent<MeshFilter>().sharedMesh;var mat=prefab.GetComponent<Renderer>().sharedMaterial;Check(mesh.vertexCount==a.positions.Length/3&&mesh.triangles.Length==a.triangles.Length,"topology "+id);var p=mesh.vertices;var n=mesh.normals;var c=mesh.colors;var uv=mesh.uv;for(int i=0;i<p.Length;i++){Check(Vector3.Distance(p[i],new Vector3(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2]))<1e-6f,"positions "+id);Check(Vector3.Distance(n[i],new Vector3(a.normals[i*3],a.normals[i*3+1],a.normals[i*3+2]))<1e-6f,"normals "+id);Check(Mathf.Abs(c[i].g-a.colors[i*3+1])<1e-6f&&Vector2.Distance(uv[i],new Vector2(a.uv[i*2],a.uv[i*2+1]))<1e-6f,"colors UV "+id);}Check(prefab.GetComponent<Renderer>().sharedMaterials.Length==1&&mat.GetFloat("_Cutoff")==0,"opaque one material "+id);var tx=mat.GetTexture("_BaseMap");Check(tx.width==256&&tx.height==256,"shared texture size "+id);var ti=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(tx));Check(ti.sRGBTexture&&ti.mipmapEnabled&&ti.filterMode==FilterMode.Trilinear&&ti.anisoLevel==2,"texture import "+id);Check(mat.IsKeywordEnabled("ROOT_GROUND")== (id!="stalagmite"),"limited root keyword "+id);if(id!="stalagmite"){var mask=mesh.uv4;Check(mask.Length==mesh.vertexCount,"ground masks");for(int i=0;i<mask.Length;i++)Check(Mathf.Abs(mask[i].x-a.rootWeights[i])<1e-6f&&mask[i].y==1,"ground weights");var tr=Array.Find(built.root.GetComponentsInChildren<MeshFilter>(),f=>f.sharedMesh==mesh).transform;var renderer=tr.GetComponent<Renderer>();var block=new MaterialPropertyBlock();renderer.GetPropertyBlock(block);var slope=block.GetVector("_TDRootSlope");Check(Mathf.Abs(slope.x-.12f)<1e-5f&&Mathf.Abs(slope.y+.04f)<1e-5f,"serialized slope convention");report.maxRootError=Mathf.Max(report.maxRootError,Probe(a,mesh,mat,tr.localToWorldMatrix,slope));}}
 var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=40;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.37f,.4f);var sun=new GameObject("Preview sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.8f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(5,-9,4));sun.gameObject.AddComponent<UniversalAdditionalLightData>();UnityEngine.Object.DestroyImmediate(built.root);
 var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.color=new Color(.26f,.22f,.18f);floor.GetComponent<Renderer>().sharedMaterial=fm;var objects=new List<GameObject>();int ordinal=0;foreach(var id in new[]{"stalagmite","flowstone","cavebreakdown"}){var o=(GameObject)PrefabUtility.InstantiatePrefab(built.prefabs[id]);o.transform.position=new Vector3((ordinal++-1)*3.3f,-.025f,0);objects.Add(o);}var person=GameObject.CreatePrimitive(PrimitiveType.Capsule);person.transform.position=new Vector3(-1.5f,.9f,-1.5f);person.transform.localScale=new Vector3(.35f,.9f,.35f);var camera=new GameObject("Preview camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.orthographic=true;camera.orthographicSize=4.4f;camera.aspect=1.3333f;camera.farClipPlane=100;
 foreach(bool tilted in new[]{false,true}){floor.transform.rotation=tilted?Quaternion.FromToRotation(Vector3.up,new Vector3(-.12f,1,.04f).normalized):Quaternion.identity;foreach(var o in objects){float h=tilted?o.transform.position.x*.12f:0;o.transform.position=new Vector3(o.transform.position.x,h-.025f,0);MapSharedProps.SharedRootGrounding.SetSlope(o.GetComponent<Renderer>(),tilted?new Vector2(.12f,-.04f):Vector2.zero);}foreach(string view in new[]{"top","oblique","walk"}){camera.transform.position=view=="top"?new Vector3(0,15,0):view=="walk"?new Vector3(7,2,-10):new Vector3(7,8,-11);camera.transform.up=view=="top"?Vector3.back:Vector3.up;camera.transform.LookAt(new Vector3(0,.6f,0));Shader.SetGlobalVector("_TDPineWind",new Vector4(.8f,.6f,1,3));Capture(camera,Path.Combine(output,"unity-"+view+"-"+(tilted?"slope":"flat")+".png"));}}
 foreach(var message in ShaderUtil.GetShaderMessages(Shader.Find("MapSharedProps/Lit")))Check(message.severity.ToString()!="Error",message.message);report.status="Passed";
 }catch(Exception e){code=1;report.status="Failed";report.error=e.ToString();Debug.LogException(e);}report.checks=count;File.WriteAllText(Path.Combine(output,"unity-cave.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}
 static float Probe(MapSharedPropsBuilder.AssetDto a,Mesh mesh,Material mat,Matrix4x4 matrix,Vector4 slope){int n=mesh.vertexCount;var positions=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);var masks=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);positions.filterMode=masks.filterMode=FilterMode.Point;var pp=new Color[n];var mm=new Color[n];for(int i=0;i<n;i++){pp[i]=new Color(a.positions[i*3],a.positions[i*3+1],a.positions[i*3+2],a.uv[i*2+1]);mm[i]=new Color(0,0,a.rootWeights[i],0);}positions.SetPixels(pp);positions.Apply();masks.SetPixels(mm);masks.Apply();var probe=new Material(Shader.Find("Hidden/MapSharedProps/RootGroundingProbe"));probe.SetTexture("_Masks",masks);probe.SetMatrix("_ProbeMatrix",matrix);probe.SetVector("_TDRootSlope",slope);probe.SetVector("_PineBand",mat.GetVector("_PineBand"));probe.SetVector("_PineWaves",mat.GetVector("_PineWaves"));probe.SetVector("_PinePhase",mat.GetVector("_PinePhase"));probe.SetVector("_PineResponse",mat.GetVector("_PineResponse"));probe.SetFloat("_PlantCombinedLimit",0);probe.SetVector("_PlantTouch",Vector4.zero);Shader.SetGlobalVector("_TDPineOrigin",Vector4.zero);Shader.SetGlobalVector("_TDPineWind",new Vector4(.8f,.6f,1,3));var rt=new RenderTexture(n,1,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();Graphics.Blit(positions,rt,probe);var previous=RenderTexture.active;RenderTexture.active=rt;var read=new Texture2D(n,1,TextureFormat.RGBAFloat,false,true);read.ReadPixels(new Rect(0,0,n,1),0,0);read.Apply();var pixels=read.GetPixels();var meshPositions=mesh.vertices;float error=0;var origin=matrix.MultiplyPoint3x4(Vector3.zero);for(int i=0;i<n;i++){var want=matrix.MultiplyPoint3x4(meshPositions[i]);want.y+=((want.x-origin.x)*slope.x+(want.z-origin.z)*slope.y)*a.rootWeights[i];error=Mathf.Max(error,Vector3.Distance(want,new Vector3(pixels[i].r,pixels[i].g,pixels[i].b)));}Check(error<.00002f,"GPU ground/zero-wind matches reference "+a.id+" "+error);RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(read);UnityEngine.Object.DestroyImmediate(probe);UnityEngine.Object.DestroyImmediate(positions);UnityEngine.Object.DestroyImmediate(masks);return error;}
 static void Capture(Camera c,string file){var rt=new RenderTexture(1200,900,24);rt.Create();c.targetTexture=rt;RenderPipeline.SubmitRenderRequest(c,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1200,900,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1200,900),0,0);image.Apply();File.WriteAllBytes(file,image.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
}
